{
  "aggregate_id": "DEF-NRS-484A-030::bus",
  "classifications": [
    {
      "class": "ru.bicycle",
      "verdict": "supported",
      "reason": "The contract describes a human-powered device, which the vehicle definition expressly excludes."
    },
    {
      "class": "ru.bus",
      "verdict": "supported",
      "reason": "Design for many passengers does not establish the ownership, capacity, use and compensation conditions needed to satisfy either admitting limb."
    },
    {
      "class": "ru.child",
      "verdict": "supported",
      "reason": "The contract describes a pedestrian person rather than a device qualifying as a vehicle."
    },
    {
      "class": "ru.commercial_motor_vehicle",
      "verdict": "supported",
      "reason": "Commercial mass or licensing does not determine whether either passenger-transport limb is satisfied."
    },
    {
      "class": "ru.electric_bicycle",
      "verdict": "supported",
      "reason": "Electric bicycles are expressly excluded from the vehicle definition required by both bus-admitting limbs."
    },
    {
      "class": "ru.electric_scooter",
      "verdict": "supported",
      "reason": "Electric scooters are expressly excluded from the vehicle definition required by both bus-admitting limbs."
    },
    {
      "class": "ru.emergency_vehicle",
      "verdict": "supported",
      "reason": "Emergency designation establishes neither satisfaction nor failure of the ownership, passenger-design, use and compensation conditions."
    },
    {
      "class": "ru.fire_apparatus",
      "verdict": "supported",
      "reason": "A fire-fighting purpose does not settle ownership, passenger capacity or transportation use under the admitting words."
    },
    {
      "class": "ru.moped",
      "verdict": "supported",
      "reason": "The moped contract does not settle whether the vehicle satisfies the non-taxicab compensated-person-transport limb."
    },
    {
      "class": "ru.motor_vehicle",
      "verdict": "supported",
      "reason": "Self-propulsion outside rails does not determine whether either bus-admitting limb applies."
    },
    {
      "class": "ru.motorcycle",
      "verdict": "supported",
      "reason": "Wheel count and astride riding do not determine whether the vehicle satisfies the compensated-person-transport limb and its taxicab exception."
    },
    {
      "class": "ru.official_vehicle",
      "verdict": "supported",
      "reason": "Official or contracted road service does not establish the ownership, passenger design and transportation use required by the admitting words."
    },
    {
      "class": "ru.pedestrian",
      "verdict": "supported",
      "reason": "The contract describes a person rather than a vehicle, and the vehicle definition also expressly excludes electric personal assistive mobility devices."
    },
    {
      "class": "ru.pedestrian_with_white_cane_or_guide_animal",
      "verdict": "supported",
      "reason": "The contract describes a pedestrian person, not a device admitted as a vehicle."
    },
    {
      "class": "ru.rail_vehicle",
      "verdict": "supported",
      "reason": "The vehicle definition excludes devices used exclusively upon stationary rails, matching the rail equipment described by this class."
    },
    {
      "class": "ru.school_bus",
      "verdict": "underdetermined",
      "reason": "School-child designation and markings do not guarantee qualifying ownership, capacity exceeding ten passengers or compensated transportation."
    },
    {
      "class": "ru.taxicab",
      "verdict": "supported",
      "reason": "The express taxicab exception bars the compensation limb, while the supplied six-person capacity ceiling prevents satisfaction of the more-than-ten-passenger limb."
    },
    {
      "class": "ru.tour_bus_or_limousine",
      "verdict": "supported",
      "reason": "The tour-or-shuttle alternative does not guarantee compensation or satisfaction of the ownership and passenger-capacity requirements of the other limb."
    },
    {
      "class": "ru.trailer_or_combination",
      "verdict": "supported",
      "reason": "Being drawn or being a combination does not settle passenger design, transportation use, ownership or compensation."
    },
    {
      "class": "ru.transit_bus",
      "verdict": "underdetermined",
      "reason": "Public transit service and identifying livery do not guarantee qualifying ownership and capacity or transportation for compensation."
    },
    {
      "class": "ru.truck",
      "verdict": "underdetermined",
      "reason": "A body built for carrying goods does not preclude additional passenger design and use satisfying an admitting limb."
    }
  ]
}

